  residencia: "(S151)S{sistema}/FILE/I01/S151/{paso}/{fecha} ON CMEMP" # WKS-TIT-INMOVIMIENTOS
  formato-fecha: yyMMdd                                               # PIC 9(06)

@ConfigurationProperties("p170")
public record P170Properties(String entrada, String residencia, String formatoFecha) {

    public String resuelve(String plantilla, int sistema, String idPaso,
                           LocalDate fechaProceso, String pack) {
        return plantilla
                .replace("{sistema}", "%03d".formatted(sistema))     // WKS-SIS-LM 9(03)
                .replace("{paso}", idPaso)                           // WKS-NOMBRE-IDPASO X(08)
                .replace("{fecha}", fechaProceso.format(DateTimeFormatter.ofPattern(formatoFecha)))
                .replace("{pack}", pack.trim());                     // WKS-B01-NOMPACMOV
    }
}

/** 01-0110-LIBRERIAS (parte final): sistema del día en B01 y fecha de proceso. */
public ContextoP170 contexto(int sistema, int csi, OptionalInt valueTarea) {
    SistemaDia b01 = libControl.consultaSistemaDia(sistema, 1, csi)      // CONSISDIA IN LIB-CONTROL
            .orElseThrow(() -> new LibreriaControlException("CONSISDIA sin resultado"));

    LocalDate fechaProceso = valueTarea.isPresent() && valueTarea.getAsInt() != 0
            ? Fechas.desdeAaaammdd(valueTarea.getAsInt())                // ATTRIBUTE VALUE OF MYSELF
            : b01.fechaProceso();   // en el fuente esta asignación está comentada (línea 1058)
    return new ContextoP170(b01.packMovimientos(), fechaProceso);
}

/** 01-0140-MUEVE-SISFEC. */
private static final DateTimeFormatter AAAAMMDD = DateTimeFormatter.BASIC_ISO_DATE;

/** A2K-CONV-AMD-TO-CAMD: la fecha de ejecución llega con año de dos dígitos. */
static LocalDate fechaCorrida(Clock reloj) {
    return LocalDate.now(reloj);                  // ACCEPT ... FROM TODAYS-DATE (MMDDAA)
}

/** A2K-CONV-CAMD-TO-AMD: la fecha de proceso de 8 dígitos se rotula con 6 (AAMMDD). */
static String rotuloArchivo(LocalDate fechaProceso) {
    return fechaProceso.format(DateTimeFormatter.ofPattern("yyMMdd"));
}

/** A2K-OBTAIN-CENTURY: AA menor que 50 es 20xx, de lo contrario 19xx (A2K-BASE-YEAR). */
private static final int PIVOTE_Y2K = 50;

static LocalDate desdeAammdd(String aammdd) {
    int aa = Integer.parseInt(aammdd.substring(0, 2));
    int siglo = (aa < PIVOTE_Y2K) ? 2000 : 1900;
    return LocalDate.of(siglo + aa, Integer.parseInt(aammdd.substring(2, 4)),
                        Integer.parseInt(aammdd.substring(4, 6)));
}

@Configuration
@EnableConfigurationProperties(P170Properties.class)
public class ReimpresionJobConfig {

    /** 00-0100-CTL-PROCESO: verificación, reimpresión y terminación. */
    @Bean
    Job reimpresionListados(JobRepository repo, Step contexto, Step reimprime) {
        return new JobBuilder("S151P170", repo)
                .start(contexto)        // 01-0000-VERIFICACION: librerías, B01, fechas
                .next(reimprime)        // 02-0000 + 03-0000
                .build();
    }

    @Bean
    Step reimprime(JobRepository repo, PlatformTransactionManager tx,
                   FlatFileItemReader<RegistroImpresion> entrada,
                   BackupRotatorioWriter salida) {
        return new StepBuilder("reimprime", repo)
                .<RegistroImpresion, RegistroImpresion>chunk(500, tx)
                .reader(entrada)        // FixedLength 150, LineMapper -> RegistroImpresion.parse
                .writer(salida)
                .build();
    }
}
// Parámetros del job: sistema (WKS-PARAM-SIS 9(03)) e idPaso (WKS-NOMBRE-IDPASO X(08)).

@Bean
@StepScope
FlatFileItemReader<RegistroImpresion> entrada(P170Properties props,
        @Value("#{jobExecutionContext['contexto']}") ContextoP170 ctx,
        @Value("#{jobParameters['sistema']}") Integer sistema,
        @Value("#{jobParameters['idPaso']}") String idPaso) {
    String titulo = props.resuelve(props.entrada(), sistema, idPaso,
                                   ctx.fechaProceso(), ctx.pack());
    return new FlatFileItemReaderBuilder<RegistroImpresion>()
            .name("archivoEnt")
            .resource(recursos.de(titulo))
            .lineMapper((linea, n) -> RegistroImpresion.parse(linea))
            .strict(true)          // OPEN INPUT falla si el archivo no existe
            .build();
}

/** 02-0150-IMPRIME-BACKUPS: cada INICI/BACK cierra el listado actual y abre otro. */
@Component
@StepScope
public class BackupRotatorioWriter implements ItemStreamWriter<RegistroImpresion> {

    private final SpoolImpresion spool;      // reemplaza PRINTER + USERBACKUPNAME
    private ListadoAbierto actual;           // W77-BACK-ABIERTO

    @Override
    public void write(Chunk<? extends RegistroImpresion> chunk) {
        for (RegistroImpresion r : chunk) {
            switch (r) {
                case RegistroImpresion.InicioBackup b -> {
                    if (actual != null) actual.cierraYGuarda();        // CLOSE MOVIMIENTOS WITH SAVE
                    actual = spool.abre(b.texto().trim());             // CHANGE ATTRIBUTE TITLE
                }
                case RegistroImpresion.SaltoPagina p -> listado().saltoDePagina(p.texto());
                case RegistroImpresion.Linea l       -> listado().avanza(l.avance(), l.texto());
            }
        }
    }

    private ListadoAbierto listado() {
        if (actual == null) {
            throw new ListadoNoAbiertoException("línea antes del primer INICI/BACK");
        }
        return actual;
    }
}

    @Override
    public void close() {
        if (actual != null) actual.cierraYGuarda();     // IF W88-BACK-ABIERTO CLOSE ... WITH SAVE
    }
}

/** 03-0100-PROCESO-TERMINA: I01-MOVIMIENTOS se abre y se cierra sin escribir nada. */
@Component
@RequiredArgsConstructor
class MarcaResidenciaListener implements StepExecutionListener {
    private final P170Properties props;

    @Override
    public ExitStatus afterStep(StepExecution step) {
        if (step.getStatus() == BatchStatus.COMPLETED) {
            recursos.creaVacio(tituloResidencia(step));   // archivo marca, cero registros
        }
        return step.getExitStatus();
    }
}
